<script setup lang="ts">
import {incomeStatus,withdrawalStatus} from './types'
const props=defineProps<{modelValue:{page:number;pageSize:number;search:string;status:string;dateFrom:string;dateTo:string};kind:'income'|'withdrawal';loading:boolean}>()
const emit=defineEmits<{'update:modelValue':[value:typeof props.modelValue];query:[];reset:[]}>()
function change(key:string,value:string){emit('update:modelValue',{...props.modelValue,[key]:value})}
</script>
<template><form class="store-search" @submit.prevent="$emit('query')"><label>{{kind==='income'?'订单号 / 说明':'付款凭证 / 说明'}}<input :value="modelValue.search" :aria-label="kind==='income'?'收入关键词':'提现关键词'" maxlength="120" :disabled="loading" @input="change('search',($event.target as HTMLInputElement).value)"></label><label>状态<select :value="modelValue.status" :aria-label="kind==='income'?'收入状态':'提现状态'" :disabled="loading" @change="change('status',($event.target as HTMLSelectElement).value)"><option value="">全部状态</option><option v-for="s in (kind==='income'?['PENDING','SETTLED','HELD']:['PENDING_REVIEW','APPROVED_PENDING_PAYMENT','PAID','REJECTED'])" :key="s" :value="s">{{kind==='income'?incomeStatus(s):withdrawalStatus(s)}}</option></select></label><label>{{kind==='income'?'订单开始日期':'申请开始日期'}}<input type="date" :value="modelValue.dateFrom" :disabled="loading" @input="change('dateFrom',($event.target as HTMLInputElement).value)"></label><label>{{kind==='income'?'订单结束日期':'申请结束日期'}}<input type="date" :value="modelValue.dateTo" :disabled="loading" @input="change('dateTo',($event.target as HTMLInputElement).value)"></label><button class="primary-button" :disabled="loading">查询</button><button type="button" class="secondary-button" :disabled="loading" @click="$emit('reset')">重置</button></form></template>
